```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc.Formatters;
using Newtonsoft.Json;

namespace Ndjson.AsyncStreams.AspNetCore.Mvc.Formatters
{
    public class NdjsonInputFormatter : TextInputFormatter
    {
        public NdjsonInputFormatter()
        {
            SupportedMediaTypes.Add("application/x-ndjson");
            SupportedEncodings.Add(Encoding.UTF8);
        }

        public override async Task<InputFormatterResult> ReadRequestBodyAsync(InputFormatterContext context, Encoding encoding)
        {
            var result = new List<object>();

            using (var reader = new StreamReader(context.HttpContext.Request.Body, encoding))
            {
                string line;
                while ((line = await reader.ReadLineAsync()) != null)
                {
                    var obj = JsonConvert.DeserializeObject(line, context.ModelType);
                    result.Add(obj);
                }
            }

            return await InputFormatterResult.SuccessAsync(result);
        }
    }

    public class NdjsonOutputFormatter : TextOutputFormatter
    {
        public NdjsonOutputFormatter()
        {
            SupportedMediaTypes.Add("application/x-ndjson");
            SupportedEncodings.Add(Encoding.UTF8);
        }

        public override async Task WriteResponseBodyAsync(OutputFormatterWriteContext context, Encoding encoding)
        {
            var response = context.HttpContext.Response;
            var buffer = new StringBuilder();

            foreach (var obj in context.Object as IEnumerable<object>)
            {
                var json = JsonConvert.SerializeObject(obj);
                buffer.AppendLine(json);
            }

            await response.WriteAsync(buffer.ToString(), encoding);
        }
    }
}
```

