using System;
using System.Collections.Generic;
using System.Security;
using System.Security.Permissions;

public class CustomResourcePermission : CodeAccessPermission
{
    public string ResourceName { get; }
    public List<string> AllowedUsers { get; }

    public CustomResourcePermission(string resourceName, List<string> allowedUsers)
    {
        ResourceName = resourceName;
        AllowedUsers = allowedUsers;
    }

    public override IPermission Copy()
    {
        return new CustomResourcePermission(ResourceName, new List<string>(AllowedUsers));
    }

    public override IPermission Intersect(IPermission target)
    {
        if (target == null)
        {
            return null;
        }

        var otherPermission = target as CustomResourcePermission;
        if (otherPermission == null || !ResourceName.Equals(otherPermission.ResourceName))
        {
            return null;
        }

        var intersectedUsers = new List<string>(AllowedUsers);
        intersectedUsers.RemoveAll(user => !otherPermission.AllowedUsers.Contains(user));

        return new CustomResourcePermission(ResourceName, intersectedUsers);
    }

    public override bool IsSubsetOf(IPermission target)
    {
        if (target == null)
        {
            return AllowedUsers.Count == 0;
        }

        var otherPermission = target as CustomResourcePermission;
        if (otherPermission == null || !ResourceName.Equals(otherPermission.ResourceName))
        {
            return false;
        }

        return AllowedUsers.All(user => otherPermission.AllowedUsers.Contains(user));
    }
}

public class Program
{
    public static void Main()
    {
        var resourcePermission1 = new CustomResourcePermission("Resource1", new List<string> { "user1", "user2" });
        var resourcePermission2 = new CustomResourcePermission("Resource1", new List<string> { "user2", "user3" });

        var intersectedPermission = (CustomResourcePermission)resourcePermission1.Intersect(resourcePermission2);
        Console.WriteLine("Intersected Users: " + string.Join(", ", intersectedPermission.AllowedUsers));

        Console.WriteLine("Is Permission 1 a subset of Permission 2? " + resourcePermission1.IsSubsetOf(resourcePermission2));
    }
}
```

